<script lang="ts">
 import { onMount, onDestroy } from 'svelte';
 import SparklesIcon from '@lucide/svelte/icons/sparkles'; import PencilIcon from '@lucide/svelte/icons/pencil'; import Trash2Icon from '@lucide/svelte/icons/trash-2'; import CheckIcon from '@lucide/svelte/icons/check'; import XIcon from '@lucide/svelte/icons/x'; import LoaderCircleIcon from '@lucide/svelte/icons/loader-circle';
 import { generateProductDrawing, listProductDrawings, updateProductDrawing, deleteProductDrawing, keepProductDrawing, ignoreProductDrawing, pendingProductDrawingContentUrl, productDrawingContentUrl, type DrawingMetadata, type PendingProductDrawing, type ProductDrawing } from '$lib/services/productDrawingService';
 let { darkMode=true }: {darkMode?:boolean} = $props();
 let drawings=$state<ProductDrawing[]>([]); let pending=$state<PendingProductDrawing|null>(null); let editing=$state<ProductDrawing|null>(null); let page=$state(1); let total=$state(0); const pageSize=12; let loading=$state(true); let busy=$state(false); let error=$state(''); let notice=$state('');
 let form=$state<DrawingMetadata>({name:'',prompt:'',description:'',keywords:'',notes:'',model:'Qwen'});
 let pages=$derived(Math.max(1,Math.ceil(total/pageSize))); let dark=$derived(darkMode); let fg=$derived(dark?'#e6edf7':'#17202d'); let muted=$derived(dark?'#91a0b7':'#627083'); let panel=$derived(dark?'#1b2230':'#fff'); let line=$derived(dark?'#30394b':'#dfe3e8');
 async function load(){ loading=true; error=''; try { const result=await listProductDrawings(page,pageSize); drawings=result.drawings; total=result.total; } catch(e){error=e instanceof Error?e.message:'Unable to load drawings';} finally{loading=false;} }
 async function generate(){ if(!form.name.trim()||!form.prompt.trim()) return; busy=true; error=''; notice=''; try{ pending=await generateProductDrawing(form); }catch(e){error=e instanceof Error?e.message:'Unable to generate drawing';}finally{busy=false;} }
 async function keep(){if(!pending)return; busy=true; try{await keepProductDrawing(pending.token); pending=null; notice='Drawing saved to the product-drawings library.'; page=1; await load();}catch(e){error=e instanceof Error?e.message:'Unable to save drawing';}finally{busy=false;}}
 async function ignore(){if(!pending)return; busy=true; try{await ignoreProductDrawing(pending.token); pending=null; notice='Generated drawing ignored.';}catch(e){error=e instanceof Error?e.message:'Unable to ignore drawing';}finally{busy=false;}}
 function startEdit(d:ProductDrawing){editing=d; form={name:d.name,prompt:d.prompt,description:d.description,keywords:d.keywords,notes:d.notes,model:d.model};}
 async function saveEdit(){if(!editing||!form.name.trim()||!form.prompt.trim())return; busy=true; try{await updateProductDrawing(editing.id,form); editing=null; notice='Drawing metadata updated.'; await load();}catch(e){error=e instanceof Error?e.message:'Unable to update drawing';}finally{busy=false;}}
 async function remove(d:ProductDrawing){if(!confirm(`Delete “${d.name}”? This also removes the image file.`))return; busy=true; try{await deleteProductDrawing(d.id); if(drawings.length===1&&page>1)page--; await load(); notice='Drawing deleted.';}catch(e){error=e instanceof Error?e.message:'Unable to delete drawing';}finally{busy=false;}}
 onMount(load); onDestroy(()=>{if(pending)void ignoreProductDrawing(pending.token).catch(()=>{});});
 </script>

<div class="page" style="background:{dark?'#10141d':'#f4f5f7'};color:{fg}">
 <header><div><p class="eyebrow">SYSTEM ADMIN / RESOURCES / PRODUCT DRAWINGS</p><h1>Generate 3D Product Drawings</h1><p class="intro" style="color:{muted}">Create technical illustrations, review the result, and manage the shared product-drawings library.</p></div><span class="model">● OpenAI Image 2.5</span></header>
 {#if error}<div class="alert error">{error}</div>{/if}{#if notice}<div class="alert success">{notice}</div>{/if}
 <section class="generator" style="background:{panel};border-color:{line}"><div class="section-title"><span>NEW DRAWING</span><small>Prompt and name are required</small></div>
  <div class="form-grid"><label>Model<select bind:value={form.model}><option value="Qwen">Qwen · Aliyun</option><option value="OpenAI">OpenAI · ChatGPT Image 2.5</option></select></label><label>Name<input bind:value={form.name} placeholder="e.g. Ventilator exploded view" /></label><label>Keywords<input bind:value={form.keywords} placeholder="ventilator, airflow, components" /></label><label class="wide">Prompt<textarea bind:value={form.prompt} rows="3" placeholder="Describe the 3D technical drawing and the parts it should show…"></textarea></label><label>Description<textarea bind:value={form.description} rows="2" placeholder="Optional description"></textarea></label><label>Notes<textarea bind:value={form.notes} rows="2" placeholder="Internal notes"></textarea></label></div>
  <button class="generate" onclick={generate} disabled={busy||!form.name.trim()||!form.prompt.trim()}><SparklesIcon size={16}/>{busy?'Generating…':'Generate drawing'}</button>
 </section>
 {#if pending}<section class="preview" style="background:{panel};border-color:{line}"><div class="section-title"><span>REVIEW GENERATED DRAWING</span><small>Nothing is permanent until you keep it</small></div><img src={pendingProductDrawingContentUrl(pending.token)} alt="Generated 3D product drawing"/><div class="preview-actions"><button class="keep" onclick={keep} disabled={busy}><CheckIcon size={16}/> Keep drawing</button><button class="ignore" onclick={ignore} disabled={busy}><XIcon size={16}/> Ignore</button></div></section>{/if}
 <div class="library-head"><div><p class="eyebrow">LIBRARY</p><h2>Existing drawings</h2></div><span style="color:{muted}">{total} drawing{total===1?'':'s'}</span></div>
 {#if loading}<div class="loading"><LoaderCircleIcon class="spin" size={24}/> Loading library…</div>{:else if drawings.length===0}<div class="empty" style="border-color:{line};color:{muted}">No saved drawings yet. Generate the first one above.</div>{:else}<div class="cards">{#each drawings as drawing (drawing.id)}<article class="card" style="background:{panel};border-color:{line}"><img src={productDrawingContentUrl(drawing.id)} alt={drawing.name}/><div class="card-body"><div class="card-title"><h3>{drawing.name}</h3><div class="card-actions"><button class="icon" title="Edit metadata" aria-label="Edit metadata" onclick={()=>startEdit(drawing)}><PencilIcon size={15}/></button><button class="icon danger" title="Delete drawing" aria-label="Delete drawing" onclick={()=>remove(drawing)}><Trash2Icon size={15}/></button></div></div>{#if drawing.description}<p>{drawing.description}</p>{/if}<small class="model-label">{drawing.model} · {drawing.model_name}</small>{#if drawing.keywords}<div class="tags">{#each drawing.keywords.split(',').map(k=>k.trim()).filter(Boolean) as keyword}<span>{keyword}</span>{/each}</div>{/if}<small class="date" style="color:{muted}">{new Date(drawing.created_at).toLocaleDateString()}</small></div></article>{/each}</div><nav class="pager"><button onclick={()=>{page--;load()}} disabled={page<=1||loading}>← Previous</button><span style="color:{muted}">Page {page} of {pages}</span><button onclick={()=>{page++;load()}} disabled={page>=pages||loading}>Next →</button></nav>{/if}
 {#if editing}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)editing=null}}><div class="modal" style="background:{panel};border-color:{line}"><div class="section-title"><span>EDIT METADATA</span><button class="icon" onclick={()=>editing=null}><XIcon size={17}/></button></div><div class="form-grid"><label>Model<select bind:value={form.model}><option value="Qwen">Qwen · Aliyun</option><option value="OpenAI">OpenAI · ChatGPT Image 2.5</option></select></label><label>Name<input bind:value={form.name}/></label><label>Keywords<input bind:value={form.keywords}/></label><label class="wide">Prompt<textarea bind:value={form.prompt} rows="4"></textarea></label><label>Description<textarea bind:value={form.description} rows="2"></textarea></label><label>Notes<textarea bind:value={form.notes} rows="2"></textarea></label></div><button class="generate" onclick={saveEdit} disabled={busy||!form.name.trim()||!form.prompt.trim()}>Save changes</button></div></div>{/if}
</div>
<style>
 .page{min-height:100%;padding:28px 32px 48px;font-family:'IBM Plex Sans','Avenir Next',sans-serif} header,.library-head{display:flex;justify-content:space-between;align-items:flex-start;gap:20px} header{padding-bottom:22px;border-bottom:1px solid #7b879522}.eyebrow{margin:0 0 9px;color:#67e8f9;font:600 10px 'IBM Plex Mono',monospace;letter-spacing:.16em}h1{margin:0;font:600 clamp(25px,3vw,40px)/1.05 'DM Sans',sans-serif;letter-spacing:-.04em}.intro{margin:11px 0 0;font-size:13px}.model{border:1px solid #7b879544;border-radius:99px;padding:8px 11px;color:#91a0b7;font:11px 'IBM Plex Mono',monospace;white-space:nowrap}.generator,.preview{margin-top:24px;padding:20px;border:1px solid;border-radius:12px}.section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.section-title span{font:600 11px 'IBM Plex Mono',monospace;letter-spacing:.14em}.section-title small{color:#91a0b7;font-size:11px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px}label{display:grid;gap:6px;color:#91a0b7;font-size:11px}label.wide{grid-column:1/-1}input,textarea,select{width:100%;box-sizing:border-box;border:1px solid #7b879544;border-radius:7px;padding:10px;background:#111722;color:inherit;font:12px 'IBM Plex Sans',sans-serif;resize:vertical}textarea{line-height:1.45}.generate,.keep,.ignore,.pager button{border:0;border-radius:7px;padding:10px 14px;display:inline-flex;align-items:center;justify-content:center;gap:7px;cursor:pointer;font:600 12px sans-serif}.generate{margin-top:16px;background:#67e8f9;color:#061419}.generate:disabled,.keep:disabled,.ignore:disabled,.pager button:disabled{opacity:.5;cursor:not-allowed}.preview img{display:block;width:100%;max-height:570px;object-fit:contain;background:#f4f1e9;border-radius:8px}.preview-actions{display:flex;gap:9px;margin-top:14px}.keep{background:#5eead4;color:#06221d}.ignore{background:#ef444422;color:#f9c7c7}.library-head{align-items:end;margin:34px 0 15px}.library-head h2{margin:0;font-size:22px}.library-head>span{font-size:12px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card{border:1px solid;border-radius:10px;overflow:hidden;box-shadow:0 10px 22px #0002}.card>img{width:100%;height:190px;object-fit:cover;background:#f4f1e9}.card-body{padding:14px}.card-title{display:flex;justify-content:space-between;gap:8px}.card h3{margin:0;font-size:14px}.card p{margin:8px 0;color:#91a0b7;font-size:12px;line-height:1.45}.card-actions{display:flex;gap:3px}.icon{border:0;background:transparent;color:#91a0b7;cursor:pointer;padding:4px}.icon:hover{color:#67e8f9}.icon.danger:hover{color:#fb7185}.tags{display:flex;flex-wrap:wrap;gap:5px}.tags span{border:1px solid #67e8f933;border-radius:99px;padding:3px 6px;color:#67e8f9;font-size:10px}.model-label{display:block;margin-top:10px;color:#67e8f9;font-size:10px}.date{display:block;margin-top:12px;font-size:10px}.pager{display:flex;justify-content:center;align-items:center;gap:18px;margin-top:24px}.pager button{background:#7b879522;color:inherit}.alert,.empty,.loading{margin-top:16px;padding:12px;border-radius:8px;font-size:12px}.error{color:#fda4af;background:#be123c22}.success{color:#5eead4;background:#05966922}.empty{border:1px dashed;text-align:center}.loading{display:flex;justify-content:center;gap:8px;color:#91a0b7}:global(.spin){animation:spin 1s linear infinite}.modal-backdrop{position:fixed;inset:0;z-index:20;display:grid;place-items:center;background:#02050aaa;padding:20px}.modal{width:min(680px,100%);padding:22px;border:1px solid;border-radius:12px;box-shadow:0 20px 70px #0008}.modal .section-title .icon{margin-left:auto}@keyframes spin{to{transform:rotate(360deg)}}
 @media(max-width:950px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:680px){.page{padding:20px 16px 35px}header{flex-direction:column}.form-grid,.cards{grid-template-columns:1fr}label.wide{grid-column:auto}}
</style>
